function updateDefaultCost() {
  const area = document.getElementById('targetArea').value;
  const type = document.getElementById('salonType').value;
  const costInput = document.getElementById('clinicTotalCost');
  const visitInput = document.getElementById('visitCount');

  if (type === 'medical') {
    if (area === 'full') { costInput.value = 240000; visitInput.value = 8; }
    else if (area === 'partial') { costInput.value = 130000; visitInput.value = 6; }
    else { costInput.value = 90000; visitInput.value = 6; }
  } else {
    if (area === 'full') { costInput.value = 180000; visitInput.value = 16; }
    else if (area === 'partial') { costInput.value = 95000; visitInput.value = 12; }
    else { costInput.value = 70000; visitInput.value = 12; }
  }
}

function calculateBreakeven() {
  const devicePrice = parseFloat(document.getElementById('devicePrice').value) || 0;
  const clinicCost = parseFloat(document.getElementById('clinicTotalCost').value) || 0;
  const transport = parseFloat(document.getElementById('transportCost').value) || 0;
  const visits = parseFloat(document.getElementById('visitCount').value) || 0;

  const clinicTotal = clinicCost + (transport * visits);
  const deviceMaintenance = 3000; // カミソリや保湿剤など最低限の消耗品費
  const deviceTotal = devicePrice + deviceMaintenance;

  const diff = clinicTotal - deviceTotal;
  const isDeviceCheaper = diff > 0;
  const perSessionEquivalent = visits > 0 ? (clinicTotal / visits) : 0;
  const breakevenSessions = perSessionEquivalent > 0 ? Math.ceil(deviceTotal / perSessionEquivalent) : 0;

  const resultBox = document.getElementById('calcResult');
  if (!resultBox) return;

  let headlineText = '';
  if (isDeviceCheaper) {
    headlineText = `家庭用脱毛器の方が約 <strong>${Math.abs(diff).toLocaleString()}円</strong> お得！ 通院 ${breakevenSessions}回分 で元が取れます`;
  } else {
    headlineText = `サロン・医療脱毛の方が約 <strong>${Math.abs(diff).toLocaleString()}円</strong> 割安（または同等）です`;
  }

  resultBox.innerHTML = `
    <div class="result-headline">結論：${headlineText}</div>
    <div class="metrics-row">
      <div class="metric-card">
        <span>家庭用脱毛器 想定総額</span>
        <strong>¥${deviceTotal.toLocaleString()}</strong>
        <small>本体＋初期ケア用品含む</small>
      </div>
      <div class="metric-card">
        <span>サロン・医療 実質総額</span>
        <strong>¥${clinicTotal.toLocaleString()}</strong>
        <small>交通費 ¥${(transport * visits).toLocaleString()} 含む</small>
      </div>
      <div class="metric-card">
        <span>損益分岐の目安</span>
        <strong>約 ${breakevenSessions} 回分</strong>
        <small>サロン施術回数換算</small>
      </div>
    </div>
  `;
}

document.addEventListener('DOMContentLoaded', calculateBreakeven);
